{
  "headline": "FDA's records trace our supply to a plant classified OAI 58 days after the shortage posting",
  "headline_cites": ["D16"],
  "sentences": [
    {
      "text": "FDA first posted the morphine sulfate injection shortage on 2017-10-31 and it remains current as of 2026-10-21.",
      "cites": ["E45", "D17"]
    },
    {
      "text": "The shortage listing names Fresenius Kabi USA, LLC, Hikma Pharmaceuticals USA, Inc., Hospira, Inc., Amphastar Pharmaceuticals, Inc., and Piramal Critical Care Inc. as affected companies.",
      "cites": ["E38", "E39", "E40", "E41", "E42"]
    },
    {
      "text": "FDA's OAI classification letter to Fresenius Kabi USA, LLC is dated 2017-12-28, 58 days after the initial shortage posting.",
      "cites": ["D16"]
    },
    {
      "text": "Fresenius Kabi's plant (FEI 3001833549) received an OAI classification after an inspection that ended 2011-07-08, with the classification known on 2017-12-28.",
      "cites": ["E21", "E32"]
    },
    {
      "text": "Hikma Pharmaceuticals USA Inc. (FEI 2220525) has had multiple VAI inspections, most recently ending 2024-06-12 with classification known 2024-12-16.",
      "cites": ["E17", "E18"]
    },
    {
      "text": "Hospira, Inc. (labeler for NDC 00409189001) appears on the shortage list with a current status since 2017-10-31.",
      "cites": ["E41", "E1", "E7"]
    },
    {
      "text": "The recommended action is to transfer 51 units of 2 mg/mL, 1 mL from Corvale General to Corvale East, which would raise Corvale East from 2.7 to 5 days on hand while Corvale General retains 14 days.",
      "cites": ["D18", "D1", "D2"]
    }
  ]
}
